#include <Arduino.h>
unsigned long retryDelayMs = 1000;
const unsigned long maximumDelayMs = 60000;
void setup() { Serial.begin(115200); }
void loop() {
    Serial.print("retry in ms: ");
    Serial.println(retryDelayMs);
    delay(retryDelayMs);
    retryDelayMs = min(retryDelayMs * 2UL, maximumDelayMs);
}

#include <Arduino.h>
unsigned long delayMs = 1000;
void setup() { Serial.begin(115200); }
void loop() { Serial.println(delayMs); delay(delayMs); delayMs = min(delayMs * 2UL, 60000UL); }
